:root {
  --ink: #28323c;
  --muted: #69737a;
  --paper: #fffdf7;
  --line: #d8d7ce;
  --navy: #173e59;
  --mint: #d9eee5;
  --mint-ink: #24664f;
  --enamel: #f0eadb;
  --body-shade: #d9bf91;
  --cervical: #b77d55;
  --white: #ffffff;
}

.case-panel {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.case-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.case-id h1 {
  margin: 3px 0 0;
  color: var(--navy);
  font-size: 23px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

.case-status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--mint-ink);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.55px;
}

.case-grid {
  display: grid;
  grid-template-columns: 88px 1fr 156px;
  gap: 14px;
  align-items: stretch;
  padding: 14px 18px;
}

.tooth-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border-radius: 12px;
  background: var(--navy);
  color: var(--white);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.7px;
  text-align: center;
}

.tooth-glyph {
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -1px;
}

.case-details {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.1;
}

.detail-row strong {
  color: var(--ink);
  font-weight: 700;
  text-align: right;
}

.shade-section {
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.shade-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.shade-chip {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 5px 7px;
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
}

.shade-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.enamel .shade-dot { background: var(--enamel); }
.body .shade-dot { background: var(--body-shade); }
.cervical .shade-dot { background: var(--cervical); }

.shade-name { color: var(--muted); }

.shade-code {
  color: var(--navy);
  font-size: 11px;
}

.case-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
  background: var(--white);
}

.technician {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.tech-initial {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 50%;
  background: var(--mint);
  color: var(--mint-ink);
  font-size: 9px;
  font-weight: 800;
}

.approve-button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: var(--navy);
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
}
